// Runs old (5264d6d) and new transforms over the same raw thread/read + rollout file.
import { readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import * as Schema from "effect/Schema";
import * as OldCodex from "<path>/src/core/codex.ts";
import { normalize as oldNormalize } from "<path>/src/core/normalize.ts";
import * as NewCodex from "./src/core/codex.ts";
import { normalize as newNormalize } from "./src/core/normalize.ts";
import { scanRollout } from "./src/core/rollout.ts";

const out: Record<string, unknown> = {};
for (const id of readFileSync("<path>", "utf8").split("\n").filter(Boolean)) {
  const raw = JSON.parse(readFileSync(`<path>/${id}.json`, "utf8")).result;
  const lines = readFileSync(raw.thread.path, "utf8").split("\n");
  const opts = { root: raw.thread.cwd, home: homedir() };
  const pick = (entries: any[]) =>
    entries.filter((e) => e.type === "action").map((e) => ({ at: e.at, kind: e.kind, status: e.status, title: e.title }));
  const oldRead = Schema.decodeUnknownSync(OldCodex.CodexThreadRead)(raw);
  const o = OldCodex.codexThreadToRows(oldRead, (OldCodex as any).scanItemTimes(lines));
  const newRead = Schema.decodeUnknownSync(NewCodex.CodexThreadRead)(raw);
  const n = NewCodex.codexThreadToRows(newRead, scanRollout(lines));
  out[id] = {
    title: (raw.thread.name ?? raw.thread.preview ?? "").split("\n")[0].slice(0, 100),
    originator: raw.thread.originator, version: raw.thread.cliVersion,
    old: pick(oldNormalize(o.activities, o.messages, opts)),
    new: pick(newNormalize(n.activities, n.messages, opts)),
  };
}
writeFileSync("<path>", JSON.stringify(out));
console.log(Object.keys(out).length);
